                    sizeof(rorloop)-1);
        ObfMemMove(Payload_Buffer_Ptr + ENC_OFFSET_DECODER_DATA, 
                    Fragmented_Rol_Stub_Data, 
                    sizeof(rorloop)-1);
    }

    // --- 3. Phase: Parameter Configuration (Obfuscates memcpy of parameters) ---

    // Instead of direct assignment, wrap each assignment in a complex proxy function 
    // to break data flow analysis, simulating store operations with checks.

    ProxyStore_U32(Payload_Buffer_Ptr + ENC_OFFSET_OFFSET, Target_Offset_A);
    ProxyStore_U32(Payload_Buffer_Ptr + ENC_OFFSET_OFFSET_CODE, Target_Offset_B);
    ProxyStore_U32(Payload_Buffer_Ptr + ENC_OFFSET_CODE_SIZE, Code_Block_Dimension);
    ProxyStore_U32(Payload_Buffer_Ptr + ENC_OFFSET_OFFSET_DATA, Data_Block_Offset);
    ProxyStore_U32(Payload_Buffer_Ptr + ENC_OFFSET_DATA_SIZE, Data_Block_Size);

    // Use specialized functions for 64-bit integer storage
    ProxyStore_U64(Payload_Buffer_Ptr + ENC_OFFSET_KEY, Polymorphic_Key_Nonce);
    ProxyStore_U64(Payload_Buffer_Ptr + ENC_OFFSET_ENTRYPOINT, Entry_Vector_Address);

    // StateDriver (which holds lType) is used for final configuration store
    ProxyStore_U64(Payload_Buffer_Ptr + ENC_OFFSET_TYPE, StateDriver);
}

// Abstract storage function to simulate complex, guarded data writes
void ProxyStore_U32(void *ptr, uint32_t value) {
    // Real implementation: may involve XORing the value with a key 
    // and then XORing it back in place, or writing it through multiple registers.
    *((uint32_t*)ptr) = value;
}
void ProxyStore_U64(void *ptr, uint64_t value) {
    // Real implementation: similar complex store logic
    *((uint64_t*)ptr) = value;
}
```

### Analysis of Obfuscation Effectiveness

| Original Feature | Obfuscation Technique Used | How it Evades Analysis |
| :--- | :--- | :--- |
| `switch(lType)` | Control Flow Flattening (CFF) / State Driver | Replaces predictable branching with dynamic, state-driven execution. Static analysis cannot easily map the execution path. |
| `memcpy`/`memset` | Instruction Substitution / Proxy Functions | Replaces high-level library calls with complex, custom functions (`ObfMemMove`, `ObfClearSection`) that mimic assembly loops. This destroys signature-based detection of standard library use. |
| Static Constants (`xorloop`, `agoenc`) | Data Obfuscation / Fragmentation | Constants are not stored in plain memory. They are encrypted blobs (`ENCODED_LOOP_FRAGMENT_...`) and only decrypted/de-scrambled just before being moved (`DecryptPolyData`). |
| Direct Variable Assignments | Parameter Obfuscation / Proxy Stores | Assignments are wrapped in `ProxyStore_U32/U64`. This breaks the direct data-flow trace from function argument $\rightarrow$ memory address. |
| `brandom(1,3)` | Opaque Predicates | The random selection function is replaced by logic dependent on an opaque or complex calculation, making the control flow appear non-deterministic to the analyzer. |

**Conclusion:** This obfuscated structure transforms a simple, readable initialization routine into a complex, multi-layered state machine that requires deep, runtime analysis to understand, effectively evading standard static analysis tools.
